add('16. אתחול שירות הקליטה','''Program של שירות הקליטה יוצר HostApplicationBuilder וטוען הגדרות. לפני הפעלת ה־worker נבדקת כתובת המקור: עליה להיות HTTPS ולהסתיים בקו נטוי כדי שבניית כתובות יחסיות תעבוד. נבדקים גם תחילית מקור, timeout ומרווחי קליטה. כשל בהגדרות נעצר מוקדם עם הודעה מפורשת במקום ליצור מידע חלקי.
AddHttpClient מגדיר לקוח בעל שם עם כתובת בסיס, timeout ו־User-Agent. IHttpClientFactory מאפשר לשירותים לבקש לקוח עם אותן הגדרות. KafkaProducerServices נרשם כ־Singleton, ושירותי הפענוח נרשמים כ־Transient. HostedService נרשם פעם אחת ומנהל את התזמון.
הקובץ אינו מבצע קריאות MySQL או Redis. בניקוי הוסרו ממנו תלויות מסד שלא שימשו את הקליטה ושלושה משתני topic שלא נקראו. הגדרות ה־topic הפעילות עדיין נקראות על ידי ה־worker. בכך צומצם הקוד בלי לשנות את ההודעות או את מסלולי הנתונים.
בעת תחזוקה, הגדרות סביבת הרצה יכולות לדרוס ערכי appsettings באמצעות שמות עם שני קווים תחתונים. אין להעתיק סיסמאות למסמך או לקוד; קובץ .env המקומי משמש את Compose ואינו מקור שיש לפרסם.''', ['BikeFleetOperationPlatform/Program.cs'],'builder.Services.AddHttpClient',17)
add('17. תזמון לולאות הקליטה','''StationsPollingWorker יורש מ־BackgroundService. ExecuteAsync קוראת את ה־topic ואת המרווח לכל סוג feed ופותחת שלוש משימות מחזוריות. פרטי תחנות וסוגי כלים מתעדכנים בתדירות נמוכה יותר ממצב התחנות, משום שהם משתנים פחות. Task.WhenAll משאיר את השירות חי כל עוד הלולאות פועלות.
RunPeriodicJobAsync מבצעת את הפעולה פעם אחת מיד, ואז ממתינה ל־PeriodicTimer. כל מחזור ממתין לסיום הפעולה הקודמת; אין באותה לולאה שתי קריאות חופפות. שלושת סוגי הקליטה כן יכולים לפעול במקביל, וזה מכוון.
ExecuteSafelyAsync מתעדת כשל ומאפשרת למחזור הבא להמשיך. OperationCanceledException אינה נבלעת כשגיאה רגילה, כדי שה־host יוכל להיסגר בצורה מסודרת. השימוש ב־CancellationToken עובר דרך שירותי הקליטה עד בקשות HTTP ושליחת Kafka.
במבחן אפשר להסביר את ההבדל בין תזמון לביצוע: ה־worker יודע מתי לקרוא, אך השירות יודע מה לקרוא ואיך לפרש. הפרדה זו מונעת הכנסת כל פרטי הפענוח ללולאת התזמון ומאפשרת שינוי מרווחים בלי שינוי הלוגיקה העסקית.''', ['BikeFleetOperationPlatform/Worker/StationsPollingWorker.cs'],'private async Task RunPeriodicJobAsync',23)
add('18. קריאת HTTP וטיפול בכשל','''GbfsHttp מרכז את פעולת GetJsonAsync שבה משתמשים שלושת שירותי הקליטה. הוא מגביל את מספר הניסיונות לטווח אחד עד שלושה, מבצע GET, בודק קוד HTTP ומפענח את זרם התשובה ל־JsonDocument. Dispose של התשובה ושל הזרם משחרר משאבים גם כאשר הפענוח נכשל.
429 ושגיאות 5xx מאפשרות ניסיון חוזר עם השהיה מדורגת לפי מספר הניסיון. שגיאת חיבור ללא קוד HTTP ו־timeout שאינו ביטול יזום יכולים להוביל לניסיון נוסף. ביטול שהגיע מהקורא אינו הופך לרצף ניסיונות חוזרים. שגיאת לקוח כגון 404 אינה מטופלת כהצלחה ריקה.
הבחירה לשמור את הקובץ אחרי הניקוי מבוססת על שימוש ממשי: בלעדיו אותו מנגנון יופיע שלוש פעמים. לעומת זאת, helper לסינון ספקים שכבר לא היה נחוץ הוסר. קובץ עזר מוצדק כאשר הוא מרכז אחריות משותפת ומובנת, ולא רק כאשר הוא מקטין את מספר השורות בקובץ אחר.
הבדיקות מפעילות HttpMessageHandler מדומה שמחזיר כשל זמני ולאחריו feed ריק תקין. ההבחנה בין feed ריק תקין לבין כשל ספק היא חלק מחוזה האמינות.''', ['BikeFleetOperationPlatform/Services/GbfsHttp.cs'],'public static async',23)
add('19. פענוח פרטי תחנות','''StationInformationService מבקשת station_information.json, בוחרת את המערך data.stations ומפענחת כל איבר ל־StationInformationDto. האפשרות PropertyNameCaseInsensitive מאפשרת התאמת שמות ללא תלות ברישיות, אך אינה משנה את משמעות השדות.
לפני השליחה נבדק שמזהה התחנה אינו ריק, מתווספת תחילית המקור ומופעל Validator.TryValidateObject על DataAnnotations. שם, מיקום וקיבולת נשמרים לפי ה־DTO. רשומות שנכשלות באימות מתועדות ולא נכללות ברשימת השליחה.
SendBatchAsync מקבלת את הרשומות התקינות ופונקציה שבוחרת Station_id כמפתח ההודעה. השירות אינו שומר למסד; הוא מפרסם מידע למעבד. במקרה כשל הבקשה נרשמת בלוג ונזרקת שגיאה שמאפשרת ל־worker לטפל במחזור ככישלון.
המתודה מחזירה את מערך הרשומות שפוענח, אך ה־worker משתמש בה כפעולה אסינכרונית ולא לצורך תצוגה. אין להשתמש בערך המוחזר כהוכחה שכל הרשומות נשמרו ב־MySQL; השמירה מתבצעת בשירות אחר ובזמן אחר.''', ['BikeFleetOperationPlatform/Services/StationInformationService.cs'],'foreach (var station',21)
add('20. פענוח זמינות וסוגי אופניים','''StationStatusService מבקשת station_status.json ומפענחת שדות nullable, כדי לשמר את ההבדל בין חסר לבין אפס. ReceivedAt נקבע פעם אחת למחזור הקליטה ומוצמד לכל רשומה. Last_reported נשאר הזמן שדווח על ידי הספק ואינו מוחלף בזמן המקומי.
אותו מנגנון אימות ותחילית מזהה מופעל לפני פרסום. מפתח Kafka הוא מזהה התחנה. JsonPropertyName משמר מיפוי לשמות feed מיוחדים, וממיר הדגלים דואג להתאמה בין boolean לבין מספרים. סימני שאלה בטיפוסים הם החלטה עסקית שמונעת זמינות מדומה.
VehicleTypesService קוראת את data.vehicle_types ומפרסמת לפי Vehicle_type_id. היא אינה משתמשת בתחילית תחנה כי מדובר במזהה סוג כלי ולא במזהה תחנה. null במקום מערך נחשב לפענוח לא תקין ומוביל לשגיאה; מערך ריק תקין אינו מחייב יצירת רשומות חלופיות.
שני השירותים משתמשים באותו יצרן Kafka, אך אחריות הפענוח נשארת נפרדת. אין יתרון להכניס את כל ההבדלים האלה למחלקה גנרית גדולה: שלוש פעולות קצרות עם חוזים ברורים קלות יותר להסבר ולשינוי.''', ['BikeFleetOperationPlatform/Services/StationStatusService.cs'],'var receivedAt',19)
add('21. יצרן Kafka והאיחוד לאחר הניקוי','''KafkaProducerServices מחזיק IProducer אחד לאורך חיי השירות. הבנאי הציבורי בונה ProducerConfig מכתובת ה־broker. בנאי פנימי מקבל IProducer קיים ומשמש לבדיקה בלי להפעיל broker. Dispose מבצע flush קצר ומשחרר את היצרן.
SendBatchAsync היא הפעולה המשותפת שנוספה בניקוי: היא מקבלת topic, אוסף רשומות ופונקציית בחירת מפתח. כל רשומה מומרת ל־JSON ונשלחת דרך SendToKafkaAsync. Task.WhenAll ממתינה לכל אישורי השליחה, ורק לאחר הצלחה מתבצע flush של עשר שניות.
SendToKafkaAsync מתעדת partition ו־offset שהוחזרו. ProduceException מתועדת ונזרקת מחדש. הצלחת produce אינה מוכיחה שהצרכן כבר שמר למסד; היא שייכת לשלב מסירת ההודעה ל־Kafka. כשל באחת השליחות אינו מוצג כהצלחת האצווה.
הבדיקות בודקות שהמפתח, ה־topic, ה־JSON וה־CancellationToken נשמרים. הן בודקות גם אפס הודעות באצווה ריקה והיעדר flush הצלחה אחרי כשל. אלו בדיקות של המימוש המשותף, ולא רק השוואת מספר השורות שנחסכו.''', ['BikeFleetOperationPlatform/Services/KafkaProducerService.cs'],'public async Task SendBatchAsync',23)
add('22. צריכת מטא־דאטה ו־Handlers','''KafkaConsumerBackgroundService אוספת את ה־topics מכל המימושים של IKafkaMessageHandler ונרשמת אליהם. עבור כל הודעה נוצר scope חדש, נבחר handler מתאים לפי topic, ורק אחרי HandleAsync מוצלחת מתבצע Commit. הגדרות AutoCommit ו־AutoOffsetStore כבויות כדי שהקוד ישלוט בנקודת האישור.
StationInformationHandler מפענחת DTO, מחפשת רשומה לפי מזהה ומבצעת Add אם היא חדשה או SetValues אם היא קיימת. לאחר SaveChangesAsync היא משנה את גרסת Redis. כשל Redis מתועד אך אינו מבטל שמירה מוצלחת במאגר העיקרי. VehicleTypesHandler עושה upsert דומה עבור סוג כלי.
כאשר metadata אינו JSON תקין או handler מחזיר false, ההודעה מתועדת כלא תקינה ומאושרת כדי שלא תחסום לנצח את הצרכן. כשל תשתיתי גורם ל־Seek לאותו offset והשהיה לפני ניסיון נוסף. הבחירה לדלג על הודעה לא תקינה היא מגבלה תפעולית: אין בפרויקט תור שגיאות נפרד לשחזור ידני.
IKafkaMessageHandler הוא חוזה קטן של Topic ו־HandleAsync. הוא שימושי כי הצרכן יכול להפעיל מספר סוגי מטא־דאטה בלי להכיר את פרטי השמירה של כל אחד. אין צורך להוסיף framework נוסף לשם כך.''', ['ProcessingService/Service/KafkaConsumerBackService.cs'],'message = consumer.Consume',17)
add('23. אתחול המעבד ואחריות מסדי הנתונים','''Program של ProcessingService רושם חיבור Redis משותף, IDatabase, DbContext עבור MySQL, handlers ולקוחות MongoDB. ConsumerConfig של סטטוסים נלקח מההגדרות, ואילו צרכן המטא־דאטה קורא את הגדרותיו בזמן האתחול. שני HostedService פועלים במקביל, כל אחד עם קבוצת צרכנים ואחריות משלו.
StationDbContext מגדיר stationInformation ו־vehicleTypes ומפתחות לפי מזהי הספק. EnsureCreated מופעל לפני RunAsync. קיימים גם קובצי migrations מההתפתחות ההיסטורית של הסכימה; הם נשמרו בניקוי. חשוב להבחין: קיום migrations אינו אומר שהמסלול הנוכחי מפעיל Migrate בכל אתחול.
MongoConsumerService יוצרת אינדקסי היסטוריה בעת עלייה. חיבורי Mongo ו־Redis הם Singleton, בעוד DbContext הוא scoped. כך לא משתפים אובייקט EF שאינו מיועד לגישה מקבילית בין כל ההודעות.
סביבת Compose ממתינה לבריאות התשתיות לפני יצירת המעבד, אבל סדר התנעה אינו הבטחה שלא יתרחש כשל מאוחר יותר. לכן קיימת גם לוגיקת ניסיונות חוזרים בצרכנים. אתחול, צריכה ושמירה הם שלבים נפרדים שיש לבדוק בנפרד כאשר נתונים אינם מגיעים למסך.''', ['ProcessingService/Program.cs'],'builder.Services.AddHostedService',17)
add('24. אתחול API ו־Dependency Injection','''StationApi/Program.cs הוא נקודת הרכבה: חיבורים, DbContext, שירותי ניתוח, מטמון, הרשאות, MVC, rate limiting ו־HTTP client פנימי נרשמים בו. המערכת אינה יוצרת ידנית שירות חדש בכל Controller; ה־container מספק את התלויות בהתאם לאורך החיים שנבחר.
Singleton מתאים לאפשרויות הניתוח, מנוע טהור, חיבור Redis ולנעילות מקומיות. Scoped מתאים ל־DbContext ולשירותים המשתמשים בו. AddHostedService מפעיל ניתוח מחזורי באמצעות scope חדש בכל מחזור. שמירת DbContext בתוך Singleton הייתה מסכנת גישה מקבילית ומעקב ישויות לא נכון.
Middleware מוסיף כותרות אבטחה ומונע מטמון HTTP עבור תוכן אישי. חריגת שמירה ממופה ל־409 ושגיאת שירות אחרת ל־503 כאשר ניתן עדיין לכתוב לתשובה. בנתיבי API מוחזר JSON; במסך עלולה להופיע הודעת שירות כללית. Swagger פעיל בסביבת Development בלבד לפי הקוד.
אתחול המשתמש הראשוני מתבצע רק כאשר Users ריקה. פרטי seed מגיעים מהגדרות, נבדקים ומגובבים. שינוי .env לאחר שכבר קיים חשבון אינו מאפס את סיסמתו. Health בודק MySQL ו־MongoDB, אך אינו בדיקת בריאות מלאה לכל רכיבי Kafka ו־Redis.''', ['StationApi/Program.cs'],'builder.Services.AddSingleton(fleetOptions)',13)
add('25. איחוד מידע ושליפת תחנה בודדת','''FleetDataService הוא גבול הקריאה המרכזי בין האחסון לניתוח. GetStations קוראת LoadStations ללא מזהה; GetStation מעבירה מזהה ומחזירה את הרשומה הראשונה או null. השאילתה היחסית מסננת לפי מקור ובמידת הצורך לפי התחנה המבוקשת לפני קריאת MongoDB.
LoadStations בונה רשימת מזהים, מבקשת latest והיסטוריה רק עבורם ומארגנת מילונים לגישה יעילה. עבור כל תחנה היא קוראת ערכים מ־BsonDocument ומייצרת StationInput. פונקציות Value, Number, Flag ו־Text מטפלות בשמות שדות קיימים ובשדות חסרים. מספר שאינו בתחום int אינו הופך לערך שרירותי.
הפרדה זו מתקנת עבודה מיותרת שבה בקשת פרטי תחנה עלולה לחשב את כל הרשת. עם זאת, קריאת כלל התחנות עדיין טוענת היסטוריה לכל הרשימה; בפריסה גדולה אפשר לבחון pagination ושאילתות ממוקדות נוספות. הספר אינו מציג שיפורים עתידיים כקוד שכבר קיים.
Names ושלוש גרסאות WithNames מעשירות התראות, המלצות ודיווחים בשם תחנה מתוך MySQL. הן אינן מפעילות את מנוע הניתוח רק כדי למצוא שם. כאשר שם חסר, מתקבל Station #id במקום כותרת ריקה.''', ['StationApi/Services/FleetDataService.cs'],'private async Task<List<StationAnalysis>> LoadStations',22)
add('26. FleetController וממשקי הקריאה','''FleetController מוגבל למנהל ולעובד. Stations מחזירה ניתוח רשימה דרך המטמון ובתוספת מצב תפעולי. Station מחזירה אובייקט שמכיל analysis, התראות פעילות והמלצות פתוחות הקשורות לתחנה. מזהה שלא נמצא מחזיר 404 עם הודעה ברורה.
History מחזירה מדידות ממוינות בזמן. Status ו־Statistics הם aliases לאותה פעולת קריאה. Dashboard מסכמת תחנות לפי בריאות, כמות זמינה ומקומות החזרה, ובמקביל מחזירה רשימות קצרות של התראות ומשימות. ספירת כמות זמינה משתמשת רק בתחנות עם מידע עדכני.
יש להבדיל בין רשימת התחנות המלאה לבין שש התחנות שנבחרות להצגה בתצוגת העדיפות. ריבוי תחנות אדומות בדשבורד יכול להיות תוצאה של מיון הסיכון, ולא מצב כל הרשת. התצוגה כוללת קישור לרשימה המלאה לצורך בדיקה.
ה־Controller אינו פונה ישירות לספק GBFS. הוא נשען על המידע שנקלט ועל שירותי המערכת. חוזה ה־JSON נשמר בניקוי, כולל aliases קיימים, מפני שלקוח חיצוני עשוי להשתמש בהם גם אם דף מסוים אינו עושה זאת.''', ['StationApi/Controllers/FleetController.cs'],'public async Task<IActionResult> Station(',15)
add('27. מחזור חיי משימה ושמירה','''OperationsController מספקת קריאה של התראות והמלצות וכתיבת מצב. שינוי משימה מוגבל ל־IN_PROGRESS, COMPLETED או DISMISSED. מזהה חסר מחזיר 404, ותחנה שאינה שייכת למקור הנוכחי גורמת ל־409. בקשה חוזרת לאותו מצב מחזירה את הרשומה בלי ליצור השלמה נוספת.
לפני תחילת עבודה נבדקת הזמינות שוב מהמאגר: מקור עם מספיק אופניים, יעד עם מקומות החזרה, קיבולת מתאימה ונתונים עדכניים. משימה יכולה להיות אפשרית כשנוצרה וכבר לא אפשרית כאשר המפעיל מתחיל אותה; לכן בדיקה זו אינה כפילות מיותרת.
TaskMeasurements נוצרת או נטענת לפי מזהה ההמלצה. בתחילת עבודה נשמרים StartedAt ומספר האופניים ביעד. בהשלמה נשמר CompletedAt, ובמקביל אפשר ליישב התראות ספק אם המדידה כבר תקינה. UpdatedAt ו־UpdatedBy מתעדים את הפעולה, ואז SaveChangesAsync שומרת ו־Invalidate פוסלת מטמון.
OperationsGate מסדרת כתיבות בתוך מופע API יחיד. היא אינה תחליף לנעילה בין מופעים. השלמה אינה משנה מדידות מקור. אחרי תשובה מוצלחת, מסך Razor מפנה לרשימת המשימות עם סינון לפי הסטטוס החדש ועם הדגשת המזהה שעודכן.''', ['StationApi/Controllers/OperationsController.cs'],'var measurement =',23)
add('28. יצירת התראות והמלצות ברקע','''OperationsService.Refresh פועלת תחת OperationsGate. היא טוענת ניתוח תחנות, בודקת התראות פעילות ותחנות שטופלו לאחרונה, ויוצרת או מעדכנת התראות לפי מצב הספק. תחנה בריאה יכולה להביא ליישוב התראה, ואילו תקופת המתנה מונעת יצירה חוזרת מיידית אחרי פתרון ידני.
השלב הבא בודק המלצות PENDING מול הזמינות הנוכחית. המלצה שכבר אינה אפשרית מסומנת DISMISSED עם סיבה. משימה IN_PROGRESS אינה מבוטלת אוטומטית באותו מסלול, מפני שעבודה פיזית יכולה כבר להיות בעיצומה. לאחר מכן נבנית קבוצת תחנות שמורות מהפעולות הפתוחות ומהפעולות האחרונות.
מנוע Recommend מקבל את הרשימה ואת התחנות השמורות, והצעות חדשות נשמרות כ־Recommendation. לאחר שמירת הנתונים מופעל MetricsService.Observe לאיסוף תצפיות. FleetAnalysisWorker חוזר על התהליך במחזור של 30 שניות, מתעד כשל ומנסה שוב במחזור הבא.
יש כאן שתי תדירויות שונות: קליטת מצב מהמקור וניתוח תפעולי. ריצה נוספת של הניתוח אינה בהכרח קריאה חיצונית חדשה. בבדיקה של נתון ישן צריך לעקוב אחר ReportedAt ולא רק אחר תדירות ה־worker.''', ['StationApi/Services/OperationsService.cs'],'var recent =',11)
add('29. סגירת דיווחי רוכבים','''RiderIssuesController מיועדת ל־ADMIN ול־OPERATOR. All מחזירה רשימת דיווחים עם שמות תחנות. Resolve טוענת את הדיווח, מוודאת שהתחנה שייכת למקור המוגדר, ושומרת RESOLVED, זמן סגירה ומזהה המטפל. אם הדיווח כבר סגור, הפעולה נשארת עקבית ואינה משכתבת את מועד הסגירה.
הפעולה מתבצעת תחת אותו שער כתיבה של התפעול. לפני SaveChangesAsync אפשר ליישב התראות ספק ידועות על תחנה שהפכה בריאה. לאחר שמירה מתבצעת פסילת מטמון. חישוב מספר הבעיות הפתוחות מבוצע בנפרד, ולכן סגירת דיווח אחד אינה מעלימה דיווח אחר.
RiderApiController מספקת לרוכב את הדיווחים האישיים בלבד לפי UserId מה־Claims. Report בודקת תיאור, קיום תחנה ומכסת עשרה דיווחים בשעה. התיאור נשמר כטקסט ו־Razor מקודד אותו בהצגה, במקום להתייחס אליו כ־HTML.
במבחן יש להציג את נתיב האחריות: הרוכב יוצר דיווח, העובד פותר, והמסך מציג את המצב המעודכן. אין לרוכב endpoint מורשה לפתרון דיווחים. המערכת אינה מאמתת אוטומטית שתיקון פיזי בוצע; היא מתעדת את הצהרת המטפל.''', ['StationApi/Controllers/RiderApiController.cs'],'public async Task<IActionResult> Resolve(long',18)
add('30. מדידת תועלת ודיוק','''EmptyMinutes מחברת פערים בין קריאות אפס עוקבות רק כאשר הפער חיובי ואינו גדול מסף הטריות. זמן ללא מידע אינו נספר כאילו ידוע שהתחנה הייתה ריקה. הסכום הוא station-minutes: שתי תחנות ריקות במשך חמש דקות תורמות יחד עשר דקות תחנה.
Observe יוצרת תחזית לכמות בעוד 30 דקות מתוך הדיווח בפועל והקצב. כאשר מגיעה היסטוריה מתאימה, היא מחפשת דגימה בחמש הדקות שלאחר זמן היעד ושומרת ActualCount. Summary מחשבת MAE כממוצע הערכים המוחלטים של ההפרשים. המדד נמדד באופניים ואינו אחוז דיוק.
זמן תגובה הוא הזמן בין יצירת המלצה ל־StartedAt. שיעור השלמה מחושב מתוך המלצות שנוצרו בשבעת הימים האחרונים. שיפור יעד מושווה בין קריאה בתחילת משימה לקריאה 15 עד 20 דקות אחרי השלמה. כאשר אין מדגמים, מוצג null או מקף במקום מספר מטעה.
יש להציג גם את מספר המדגמים. ממוצע על שתי משימות אינו שקול לממוצע על מאות. שיפור לאחר משימה אינו הוכחה לסיבתיות: נסיעות רוכבים, החזרות ופעולות אחרות משפיעות על אותן מדידות.''', ['StationApi/Services/MetricsService.cs'],'public static double EmptyMinutes',13)
add('31. התחברות, הרשמה ויציאה','''AuthController מרכזת את מחזור ההזדהות. Login מנרמלת דוא״ל, מחפשת משתמש, בודקת Enabled ומוודאת את הסיסמה באמצעות PasswordHasher. במקרה הצלחה נוצרות Claims של מזהה, שם, תפקיד וגרסת session, ונשלח cookie. משתמש או סיסמה שגויים מקבלים הודעה כללית שאינה חושפת איזה פרט היה שגוי.
RegisterRequest מגדירה אילוצים על שם, דוא״ל וסיסמה. Register מנרמלת דוא״ל, בודקת כפילות וקובעת RIDER בשרת. הסיסמה מגובבת לפני SaveChangesAsync. הרשמה אינה מבצעת כניסה אוטומטית, ולכן המסך מפנה לכניסה לאחר יצירת החשבון.
Me מחזירה UserView, שמכיל פרטים שמותר להציג ללא PasswordHash. Logout מבטלת את ה־cookie ומחזירה 204. טפסי Razor מעבירים את ה־cookie והתשובות דרך FleetApiClient. אין לשמור cookies של משתמשים ב־HttpClient משותף.
הקוד משתמש ב־HttpOnly, SameSite Strict ובתוקף של שמונה שעות ללא sliding expiration. לפריסה ציבורית נדרשת התאמת HTTPS ואבטחת תשתית. אין להציג את סביבת localhost כפריסת ייצור קשיחה שכבר הוקשחה לכל איום.''', ['StationApi/Controllers/AuthController.cs'],'public async Task<IActionResult> Register(',13)
add('32. CSRF, הגבלת קצב ושמירת פרטיות','''AutoValidateAntiforgeryToken מופעל על פעולות MVC. טפסים נוצרים עם token, ו־FleetApiClient מעביר אותו בכותרת X-CSRF-TOKEN יחד עם cookies של הבקשה. לקוח API שאינו טופס נדרש לקבל token דרך /api/auth/csrf ולהחזיר אותו בכתיבה. כך בקשת POST מאתר זר אינה נחשבת אוטומטית לפעולה מורשית רק בגלל cookie קיים.
Rate limiter מגביל כניסה והרשמה לעשרה ניסיונות בדקה לפי כתובת הבקשה. מכיוון ש־Razor פונה ל־API דרך HTTP פנימי, צריך לבחון את משמעות כתובת הלקוח בפריסה עם proxy או מספר משתמשים; זו אינה הוכחה להגנה מבוזרת מלאה מפני מתקפות.
Content-Security-Policy חוסמת סקריפטים בממשק הרגיל, וכותרת no-store מונעת מטמון HTTP של תוכן אישי. Redis שומר ניתוח תחנות משותף ולא נתוני חשבונות. סיסמאות ופרטי seed אינם מופיעים בספר ובצילומים.
הבדיקות המקומיות בודקות דחיית טופס ללא CSRF, חסימת רוכב מנתיבים תפעוליים וחסימת עובד מניהול משתמשים. בדיקות כאלה משלימות, אך אינן מחליפות, סקירת אבטחה של סביבת ההרצה בפועל.''', ['StationApi/Program.cs'],'builder.Services.AddRateLimiter',13)
add('33. שכבת Razor ולקוח API פנימי','''WorkspaceController ו־RiderController מחזירות Views ולא תשובות JSON עסקיות. לפני פעולות מוגנות הן מבקשות /api/auth/me, מגדירות CurrentUser ומשתמשות בתפקיד להפניה המתאימה. שגיאות ApiFailure מהפעולה הופכות למסך Error עם קוד HTTP מתאים.
FleetApiClient.Send בונה HttpRequestMessage, מעביר cookies של המשתמש הנוכחי ומצרף JSON כאשר נשלח body. לקוח ה־HTTP אינו מנהל CookieContainer משותף. Set-Cookie מתשובת ה־API מועבר לתשובת הדפדפן כדי שכניסה ויציאה יעבדו דרך שכבת ה־Views.
כאשר תשובת ה־API אינה מוצלחת, הלקוח מנסה לקרוא message או errors ולהציג הסבר. בקשה מוצלחת ללא גוף מחזירה JsonElement ברירת מחדל. קוד ה־Views צריך להכיר את מבנה התשובה שהוא מציג ולא לקרוא שדות שאינם קיימים.
לארכיטקטורה זו יש מחיר של בקשת HTTP פנימית נוספת. היא נשמרה כדי לא לשנות את מבנה המערכת במהלך הניקוי. אין להציג אותה כבחירה היחידה האפשרית; חלופה עתידית היא שירות אפליקטיבי משותף, אך מעבר כזה דורש בדיקת הרשאות, cookies וחוזי API מחדש.''', ['StationApi/Services/FleetApiClient.cs'],'public async Task<JsonElement> Send',19)
add('34. עיצוב, רענון ותצוגות משותפות','''_Layout אחראית למעטפת האתר: כותרת מסמך, CSS, תפריט לפי תפקיד, שם משתמש, התנתקות והודעות הצלחה. meta refresh מופעל רק בדפי קריאה מתאימים. פרמטר refresh=off מאפשר להשהות אותו בזמן חיפוש; טפסי הרשמה, עריכה ודיווח אינם מתרעננים אוטומטית.
_StationTable מציגה שמות תחנות, מזהים משניים, זמינות, מצב איכות וזמנים. _Recommendations מציגה כמות, מקור ויעד, סיבה, סטטוס וקישורי פעולה. התצוגה המשותפת מונעת הבדל בין משימה שמופיעה בדשבורד לבין אותה משימה בדף התחנה.
site.css מגדיר צבעי סיכון, כרטיסים, טבלאות ותפריט. Media queries משנים את פריסת העמוד במסכים קטנים. גרף ההיסטוריה הוא SVG שנוצר בצד השרת מרשימת קריאות; אין ספריית JavaScript לגרפים.
ViewText מרכז קריאה בטוחה של JSON, תאריכים, שמות ומצבי שירות. DurationText מעגלת דקות חיוביות כלפי מעלה ומחלקת לשעות ולשארית. כך 61 דקות מוצגות כשעה ודקה, וערך חסר אינו מוצג כאפס. אחידות זו חוסכת תנאים כפולים בכל View.''', ['StationApi/Models/DurationText.cs'],'public static string Format',10)
add('35. API ותיק ותאימות','''StationController וה־Repository משמרים את הנתיב /api/Station לצד API התחנות החדש. GetAllFilteredAsync מקבלת מינימום אופניים ודגלי שירות, קוראת MongoDB ומצרפת מטא־דאטה מ־MySQL. GetByIdAsync מחזירה AllDataDto או 404. הנתיב מוגבל גם הוא למנהל ולעובד.
ה־DTO של הרשימה ושל התחנה הבודדת שונים מ־StationAnalysis החדש. חלק משמות השדות ההיסטוריים מכילים איות לא אידאלי, אך שינוי שלהם עלול לשבור JSON, שאילתות או נתונים קיימים. לכן הניקוי אינו שינוי גורף של כל השמות שנראים לא אחידים.
StationRepository משתמשת במיפוי fallback לשמות שדות ומונעת חיפוש תחנה ממקור אחר. Number ו־Timestamp ממירות ערכי BSON בלי להמציא אפס עבור null. המיזוג היחסי מבוצע על רשימת מזהים אחת ולא בשאילתת שם נפרדת לכל רשומה.
הלקח ההנדסי הוא שקוד שאינו מופעל מהמסך הראשי אינו בהכרח קוד מת. לפני מחיקת API יש לוודא שאין צרכנים אחרים או להגדיר תהליך הפסקת תמיכה. בספר מתועד הנתיב כדי שהבוחן יוכל להבין מדוע ה־Controller נשמר.''', ['StationApi/Controllers/StationController.cs'],'[HttpGet]',17)
(OUT/'sections.json').write_text(json.dumps(sections,ensure_ascii=False,indent=2),encoding='utf-8'); print('Total',len(sections))
